const { tipo, nome_arquivo, cliente_id } = $input.first().body;

const tipos_validos = ['NF', 'RG', 'CPF', 'Contrato', 'CNAE'];
const extensoes_validas = ['.pdf', '.jpg', '.png'];

const tem_extensao = extensoes_validas.some(ext => nome_arquivo.toLowerCase().endsWith(ext));
const tipo_valido = tipos_validos.includes(tipo);

return {
  isValid: tem_extensao && tipo_valido,
  tipo: tipo || 'Desconhecido',
  nome_arquivo,
  cliente_id: cliente_id || null,
  timestamp: new Date().toISOString()
};

// Simula OCR/extração de dados
const tipo = $node["Validar Documento"].output.first().json.tipo;

let campos_extraidos = {};

if (tipo === 'NF') {
  campos_extraidos = { numero: '2024-001', valor: '1500.00', data: '2024-08-11' };
} else if (tipo === 'RG') {
  campos_extraidos = { nome: 'João Silva', cpf: '123.456.789-00', valido: true };
} else if (tipo === 'Contrato') {
  campos_extraidos = { tipo_contrato: 'Fornecimento', vigencia: '24 meses' };
}

return {
  campos_extraidos,
  confianca_extracao: 0.95,
  status: 'processado'
};

